@extends('layouts.app') @section('title',$supplier->exists?'Edit Supplier':'New Supplier') @section('content')<form method="post" action="{{ $supplier->exists?route('suppliers.update',$supplier):route('suppliers.store') }}">@csrf @if($supplier->exists)@method('put')@endif<div class="card"><div class="form-grid"><label>Name<input name="name" value="{{ old('name',$supplier->name) }}" required></label><label>Contact person<input name="contact_person" value="{{ old('contact_person',$supplier->contact_person) }}"></label><label>Phone<input name="phone" value="{{ old('phone',$supplier->phone) }}"></label><label>Email<input type="email" name="email" value="{{ old('email',$supplier->email) }}"></label><label>TRN<input name="trn" value="{{ old('trn',$supplier->trn) }}"></label><label>Status<select name="status"><option value="active" @selected(old('status',$supplier->status?:'active')==='active')>Active</option><option value="inactive" @selected(old('status',$supplier->status)==='inactive')>Inactive</option></select></label><label class="span-2">Address<textarea name="address">{{ old('address',$supplier->address) }}</textarea></label></div><div class="actions"><a class="btn" href="{{ route('suppliers.index') }}">Cancel</a><button class="btn primary">Save supplier</button></div></div></form>@endsection
